and we recall that the function $\phi(s,x,y)$ is given by \eqref{eq:phi}.

\begin{align}
v_r(t, r,z)&=\lambda\mathbb{E}\left[\int_t^{\tau_r^t \wedge T} e^{-\rho s-R_s^{t, r}} f(s)ds\right]+(1-\lambda)\eta  \mathbb{E}\left[ \int_t^{\tau_r^t \wedge T}e^{-\rho s-R^{t,r}_s}Z_s^{t,z} ds\right], \label{eq:v-r}\\
v_{rr}(t,r,z)&=\lambda \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s-r+x}\phi(s-t,x,r)f(s)dx ds-\lambda  \mathbb{E}\left[\int_{t}^{\tau_r^t\wedge T} e^{-\rho s-R_s^{t,r}}f(s)ds\right]\nonumber\\
&\quad+(1-\lambda)\eta z\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s-r+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi(s-t,x,r)dx ds\nonumber\\
&\quad-(1-\lambda)\eta  \mathbb{E}\left[ \int_t^{\tau_r^t \wedge T}e^{-\rho s-R^{t,r}_s}Z_s^{t,z} ds\right],\label{eq:v-rr}
\end{align}

For $(t,r)\in [0,T]\times \mathds{R}_+$, let us denote 
\begin{align}
h(t,r)&:=-(1-\lambda)\eta \mathbb{E}\left[ \int_t^T\exp\left(-\rho s-R^{t,r}_s+\left(\mu_Z-\frac{\sigma_Z^2}{2}\right)(s-t)+\sigma_Z(W_s-W_t)\right) ds\right],\label{eq:h}\\
l(t,r)&:=-\lambda\mathbb{E}\left[ \int_t^Te^{-\rho s-R^{t,r}_s}f(s) ds\right].\label{eq:l}
\end{align}
Then, $v(t,r,z)=zh(t,r)+l(t,r)$ for $(t,r,z)\in \overline{\mathcal{D}}_T$. By a similar calculation as in the proof of Proposition  4.1 in \cite{BoLiaoYu21} and in the proof of Lemma 3.4 in \cite{BHY24a}, we can obtain 
\begin{align}
l_r(t, r)&=\lambda\mathbb{E}\left[\int_t^{\tau_r^t \wedge T} e^{-\rho s-R_s^{t, r}} f(s)ds\right].\label{eq:l-r-1}\\
zh_r(t, r)&=(1-\lambda)\eta z\mathbb{E}\left[ \int_t^{\tau_r^t \wedge T}\exp\left(-\rho s-R^{t,r}_s+\left(\mu_Z-\frac{\sigma_Z^2}{2}\right)(s-t)+\sigma_Z(W_s-W_t)\right) ds\right].\nonumber\\
l_{rr}(t,r)&=\lambda  \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s-r+x}\phi(s-t,x,r)f(s)dx ds-\lambda  \mathbb{E}\left[\int_{t}^{\tau_r\wedge T} e^{-\rho s-R_s^{t,r}}f(s)ds\right].\label{eq:l-r-2}\\
zh_{rr}(t,r)&=(1-\lambda)\eta z\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s-r+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi(s-t,x,r)dx ds\nonumber\\
&\quad-(1-\lambda)\eta z \mathbb{E}\left[ \int_t^{\tau_r^t \wedge T}\exp\left(-\rho s-R^{t,r}_s+\left(\mu_Z-\frac{\sigma_Z^2}{2}\right)(s-t)+\sigma_Z(W_s-W_t)\right) ds\right],\nonumber
\end{align}
and 
\begin{align}
l_{rrr}(t,r)&=-2\lambda  \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s-r+x}\phi(s-t,x,r)f(s)dx ds+\lambda  \mathbb{E}\left[\int_{t}^{\tau_r\wedge T} e^{-\rho s-R_s^{t,r}}f(s)ds\right]\nonumber\\
&\quad+\lambda  \int_{t}^{T} e^{-\rho s}\phi(s-t,r,r)f(s) ds+\lambda  \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s-r+x}\phi_r(s-t,x,r)f(s)dx ds,\label{eq:l-r-3}\\
h_{rrr}(t,r)&=-2(1-\lambda)\eta\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s-r+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi(s-t,x,r)dx ds\nonumber\\
&\quad+(1-\lambda)\eta \mathbb{E}\left[ \int_t^{\tau_r^t \wedge T}\exp\left(-\rho s-R^{t,r}_s+\left(\mu_Z-\frac{\sigma_Z^2}{2}\right)(s-t)+\sigma_Z(W_s-W_t)\right) ds\right]\nonumber\\
&\quad+(1-\lambda)\eta\int_{t}^{T} \exp\left(-\rho s-\frac{\sigma\sigma_Z}{\mu}r+\kappa(s-t)\right) \phi(s-t,r,r)dx ds\label{eq:h-r-3}\\
&\quad-(1-\lambda)\eta\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s-r+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi_r(s-t,x,r)dx ds.\nonumber
\end{align}
From \eqref{eq:l-r-1}-\eqref{eq:h-r-3}, we deduce \eqref{eq:v-r}-\eqref{eq:v-rr} and $v_{rrr}=l_{rrr}+zh_{rrr}$ is continuous in $(t,r,z)$. We next derive the expression of $v_z,v_{zz},v_{rz}$ and $v_{rrz}$. Note that  $v(t,r,z)=zh(t,r)+l(t,r)$, it holds that, for $(t,r,z)\in\overline{\mathcal{D}}_T$,
\begin{align}\label{eq:v-z}
v_z(t,r,z)=h(t,r),\quad v_{zz}(t,r,z)=0,\quad v_{rz}(t,r,z)=h_r(t,r,z)\quad v_{rrz}(t,r,z)=h_{rr}(t,r,z).
\end{align}
Finally, we derive the expression of $v_t$ and $v_{rt}$. For any $\delta\in[-t,T-t]$, it holds that
\begin{align*}
l(t,r)&=-\lambda \mathbb{E}\left[\int_{t}^T e^{-\rho s-R_s^{t,r}}f(s)ds\right]=-\lambda \mathbb{E}\left[\int_{t}^{T}e^{-\rho s-R_{s+\delta}^{t+\delta,r}}f(s)ds\right].
\end{align*}
Then, we get
\begin{align*}
&\lim_{\delta\to 0}\frac{l(t+\delta,r)-l(t,r)}{\delta}\\
&=-\lambda \lim_{\delta\to 0}\frac{1}{\delta}\left\{ \mathbb{E}\left[\int_{t+\delta}^{T} e^{-\rho s-R_{s}^{t+\delta,r}}f(s)ds\right]-\mathbb{E}\left[ \int_t^Te^{-\rho s-R^{t+\delta,r}_{s+\delta}}f(s)ds\right] \right\}\\
&=\lambda\lim_{\delta\to 0}\frac{1}{\delta}\mathbb{E}\left[\int_t^{t+\delta}e^{-\rho s-R_{s}^{t+\delta,r}}f(s)ds\right]-\lambda  \int_{t}^{T} e^{-\rho s}f(s)\lim_{\delta\to 0}\left\{\frac{1}{\delta}\mathbb{E}\left[e^{-R_{s}^{t+\delta,r}}-e^{-R^{t+\delta,r}_{s+\delta}}\right]\right\}ds\\
&=\lambda e^{-\rho t-r}f(t)-\lambda  \int_{t}^{T} e^{-\rho s}f(s)\lim_{\delta\to 0}\left\{\frac{1}{\delta}\mathbb{E}\left[e^{-R_{s}^{t+\delta,r}}-e^{-R^{t+\delta,r}_{s+\delta}}\right]\right\}ds.
\end{align*}
By applying It\^o's lemma and taking expectation, we have $\mathbb{E}\left[e^{-R_{s}^{t+\delta,r}}-e^{-R^{t+\delta,r}_{s+\delta}}\right]=-\rho \delta-\mathbb{E}\left[\int_{s+\delta}^s  dL_{\ell}^{t+\delta,r}\right]$. Using the Dominated Convergence Theorem and Proposition~2.5 in \cite{Abraham2000}, we arrive at
\begin{align}\label{eq:l-t-1}
l_t(t,r)=\lambda e^{-\rho t-r}f(t)+\lambda  \int_{t}^{T} e^{-\rho s}f(s)(\rho-p(t,r;s,0))ds,
\end{align}
where $p(t,r;s,x)$ is the conditional density function of the reflected drifted Brownian process $R^{t,r}$ \citep{Vee2004}. Similar to the calculation above, we can also get
\begin{align}\label{eq:h-t-1}
zh_t(t,r)
&=(1-\lambda)\eta \left\{\mathbb{E}\left[ \int_{t}^{T} e^{-\rho s-R^{t,r}_{s}} Z_{s}^{t,z} ds\right]+\mathbb{E}\left[  e^{-\rho T-R^{t,r}_{T}} Z_{T}^{t,z} \right]\right\}.
\end{align}
We also have from \eqref{eq:v-r} that
\begin{align}\label{eq:v-t-2}
&v_{rt}(t,r)=-\lambda \int_t^T \int_0^r \int_{-\infty}^y e^{-\rho s-r+x}\phi_s(s-t,x,y)dsdyds\\
&\quad-(1-\lambda)\eta z\int_{t}^{T}\int_0^r \int_{-\infty}^{y} \exp\left(-\rho s-r+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi_s(s-t,x,y)dx dyds.\nonumber
\end{align}
By applying \eqref{eq:l-r-1}, \eqref{eq:l-r-2}, \eqref{eq:v-z} \eqref{eq:l-t-1} and \eqref{eq:h-t-1},  we deduce that $v \in {{\tt{C}}}^{1,2,2}(\overline{\mathcal{D}}_T)$. Using \eqref{eq:l-r-2}, \eqref{eq:l-r-3}, \eqref{eq:h-r-3}, \eqref{eq:v-z} and \eqref{eq:v-t-2}, we further have that $v_r \in {{\tt{C}}}^{1,2,2}(\overline{\mathcal{D}}_T)$.

\begin{align*}
&\lim_{\delta\to 0}\frac{l(t+\delta,r)-l(t,r)}{\delta}\\
&=-\lambda \lim_{\delta\to 0}\frac{1}{\delta}\left\{ \mathbb{E}\left[\int_{t+\delta}^{T} e^{-\rho s-R_{s}^{t+\delta,r}}f(s)ds\right]-\mathbb{E}\left[ \int_t^Te^{-\rho s-R^{t+\delta,r}_{s+\delta}}f(s)ds\right] \right\}\\
&=\lambda\lim_{\delta\to 0}\frac{1}{\delta}\mathbb{E}\left[\int_t^{t+\delta}e^{-\rho s-R_{s}^{t+\delta,r}}f(s)ds\right]-\lambda  \int_{t}^{T} e^{-\rho s}f(s)\lim_{\delta\to 0}\left\{\frac{1}{\delta}\mathbb{E}\left[e^{-R_{s}^{t+\delta,r}}-e^{-R^{t+\delta,r}_{s+\delta}}\right]\right\}ds\\
&=\lambda e^{-\rho t-r}f(t)-\lambda  \int_{t}^{T} e^{-\rho s}f(s)\lim_{\delta\to 0}\left\{\frac{1}{\delta}\mathbb{E}\left[e^{-R_{s}^{t+\delta,r}}-e^{-R^{t+\delta,r}_{s+\delta}}\right]\right\}ds.
\end{align*}

\begin{align}\label{eq:h-t-1}
zh_t(t,r)
&=(1-\lambda)\eta \left\{\mathbb{E}\left[ \int_{t}^{T} e^{-\rho s-R^{t,r}_{s}} Z_{s}^{t,z} ds\right]+\mathbb{E}\left[  e^{-\rho T-R^{t,r}_{T}} Z_{T}^{t,z} \right]\right\}.
\end{align}

It follows from Proposition \ref{prop:v} that the function  $\hat{u}(t,y,z)$ is the  unique classical solution of the dual equation \eqref{eq:dual-u} satisfying $|\hat{v}(t,y,z)|\leq K(1+z)$ for some positive constant $K$ and $\hat{u}_y \in {{\tt{C}}}^{1,2,2}([0,T]\times (0,1]\times\mathds{R}_+)$. Furthermore, the strict convexity of $(0,1] \ni y \mapsto \hat{u}(t,y)$ for fixed $t \in[0, T) $ follows from the fact that 
\begin{align*}
&\hat{u}_{y y}=\frac{e^{\rho t}}{y^2}(v_{rr}+v_r)=\frac{\lambda e^{\rho t}}{y^2} \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s-r+x}\phi(s-t,x,r)f(s)dx ds\\
&\qquad+\frac{(1-\lambda)\eta e^{\rho t}}{y^2}\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s-r+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi(s-t,x,r)dx ds>0.
\end{align*} 
By Lemma \ref{lem:derivative-v}, we that $f(t)\geq 0$ and $\eta=(\mu_Z\sigma-\mu\sigma_Z)/\sigma>0$.

\begin{align*}
&\hat{u}_{y y}=\frac{e^{\rho t}}{y^2}(v_{rr}+v_r)=\frac{\lambda e^{\rho t}}{y^2} \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s-r+x}\phi(s-t,x,r)f(s)dx ds\\
&\qquad+\frac{(1-\lambda)\eta e^{\rho t}}{y^2}\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s-r+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi(s-t,x,r)dx ds>0.
\end{align*}

The proof of the item  (i) is similar to the proof of Theorem 5.1 in \cite {BoLiaoYu21}, and hence we omit it here. Mext, we only show the item (ii). It is not difficult to see that
\begin{align}\label{eq:theta-1}
\lim_{y\downarrow 0}z \hat{u}_{yz}(t,y,z)&=-\lim_{y\downarrow 0}\frac{e^{\rho t}z}{y}v_{rz}(t,-\ln y,z)=-\lim_{r\to +\infty}e^{\rho t+r}zv_{rz}(t,r,z)\nonumber\\
&=-(1-\lambda)\eta\mathbb{E}\left[\int_t^{T} e^{-\frac{\mu}{\sigma}\left(W_s-W_t\right)-\frac{\mu^2}{2\sigma^2}(s-t)}  Z_s^{t,z}ds\right]\nonumber\\
&=-(1-\lambda)\left(e^{\eta (T-t)}-1\right)z.
\end{align}
In view of $\mu>0$, \eqref{eq:v-rr} and $\hat{u}_{yy}\geq 0$ from Proposition \ref{thm:dual-u}, we have 
\begin{align}\label{eq:estimate-theta-1}
0\leq\liminf_{y\downarrow 0} y\hat{u}_{yy}(t,y,z)\leq \limsup_{y\downarrow 0} y\hat{u}_{yy}(t,y,z)=\limsup_{r\to +\infty} e^{\rho t+r}(v_{rr}+v_r)(t,r,z).
\end{align}
We obtain from Lemma \ref{lem:derivative-v} that
\begin{align}\label{eq:estimate-theta-2}
e^{r}(v_{rr}+v_r)(t,r,z)\nonumber\\
&\quad=\lambda \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s+x}\phi(s-t,x,r)f(s)dx ds\\
&\qquad +(1-\lambda)\eta z\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi(s-t,x,r)dx ds.\nonumber
\end{align}
In the sequel, let $C>0$ be a generic positive constant independent of $(t,x,z)$, which may differ from line to line. For the case $r>2$, it holds that $(r+y)^2-1>0$ for all $y\geq0$. As $f\in C([0,T])$, it follows that, for all $(t,r)\in[0,T]\times (2,\infty)$,
\begin{align}\label{eq:estimate-theta-3}
&\int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s+x}\phi(s-t,x,r)f(s)dx\leq C \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s+x}\phi(s-t,x,r)dx ds\nonumber\\

&\overset{y=r-x}{=}C\int_{t}^{T}\int_{0}^{\infty} e^{-\rho s+r-y}\frac{2( r+y)}{\hat{\sigma}^2\sqrt{2\hat{\sigma} \pi (s-t)^3}}\exp\left(\frac{\hat{\mu}}{\hat{\sigma}}(r-y)-\frac{1}{2} \hat{\mu}^2 (s-t)-\frac{( r+y)^2}{2\hat{\sigma}^2 (s-t)}\right)dyds\nonumber\\
&=C\int_{t}^{T}\frac{2\exp\left(-\frac{1}{2\hat{\sigma}^2 (s-t)}\right)}{\hat{\sigma}^2\sqrt{2\hat{\sigma} \pi (s-t)^3}}e^{-\rho s}ds\int_{0}^{\infty} ( r+y)\exp\left(\frac{\hat{\mu}}{\hat{\sigma}} (r-y)+r-\frac{( r+y)^2-1}{2\hat{\sigma} ^2(T-t)}\right)dy\nonumber\\
&\leq C r\exp\left(\left(\frac{\hat{\mu}}{\hat{\sigma}}+1\right)r-\frac{r^2-1}{2\hat{\sigma}^2 (T-t)}\right)\int_{0}^{\infty} ( 1+y)\exp\left(-\frac{y^2}{2\hat{\sigma}^2 (T-t)}-\frac{\hat{\mu}}{\hat{\sigma}}y\right)dy\nonumber\\
&\leq Cr\exp\left(\frac{\hat{\mu}}{\hat{\sigma}}r+r-\frac{r^2-1}{2\hat{\sigma}^2 (T-t)}\right).
\end{align}
Since the mapping $r\to r\exp(\frac{\hat{\mu}}{\hat{\sigma}} r+r-\frac{r^2-1}{2\hat{\sigma}^2 (T-t)})$ is continuous, and
$\lim_{r\to\infty}r\exp(\frac{\hat{\mu}}{\hat{\sigma}}r +r-\frac{r^2-1}{2\hat{\sigma}^2 (T-t)})=0$, we have 
\begin{align}\label{eq:estimate-theta-4}
&\limsup_{r\to+\infty}\int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s+x}\phi(s-t,x,r)f(s)dx\leq 0.
\end{align}
In a similar fashion to derive \eqref{eq:estimate-theta-3}, we can also get that
\begin{align}\label{eq:estimate-theta-5}
&\limsup_{r\to+\infty}\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi(s-t,x,r)dx ds\leq 0.
\end{align}
Therefore, in view of \eqref{eq:estimate-theta-1} \eqref{eq:estimate-theta-2}, \eqref{eq:estimate-theta-4} and \eqref{eq:estimate-theta-5}, we deduce that
\begin{align}\label{eq:theta-2}
\lim_{y\downarrow 0} y\hat{u}_{yy}(t,y,z)=0.
\end{align}
Together with \eqref{eq:theta-1}, the  feedback control function $\theta^*(t,x,z)$ give by \eqref{eq:optimal-theta} is well-defined.
Moreover, we can see that the function $(x,z) \to \theta^*(t,x,z)$ is locally Lipschitz continuous and satisfies the liner growth with respect to $z$.











Thus, the SDE \eqref{eq:optimal-SDE} has a unique strong solution, which implies $\theta^*\in\mathbb{U}^r$. 

 For any $\theta\in \mathbb{U}^r$, let $(X_t)_{t\in[ 0,T]}$ be the resulting state process. For $n\in \mathbb{N}$ and $1/n<T$, define the stopping time $\tau_n$ by $\tau_n:=\left(T-\frac{1}{n}\right)\wedge\inf \left\{s\geq 0: X_s \wedge Z_s\geq n\right\}$. By applying It\^o's lemma to $e^{-\rho \tau_n}u(\tau_n,X_{\tau_n},Z_{\tau_n})$ and  taking the expectation on both sides, we deduce
\begin{align}\label{eq:value-ineq}
\mathbb{E}\left[e^{-\rho (\tau_n-t)}u(\tau_n,X_{\tau_n},Z_{\tau _n})\right]+\mathbb{E}\left[-\int_t^{\tau_n}e^{-\rho (s-t)}dL_s^X\right]\leq u(t,x,z),
\end{align}
and the equality holds when $\theta=\theta^*$. In view of Proposition \ref{thm:dual-u} and \eqref{eq:sol-u}, we know that $u(t,x,z)\leq 0$ on $\overline{\mathcal{D}_T}$ and $u(t,x,z)=\inf_{y\in(0,1]}\{\hat{u}(t,y,z)+yx\}\geq \inf_{y\in(0,1]}\{\hat{u}(t,y,z)\}\geq -C(1+z)$ on $\mathcal{O}_T$ for some positive constant $C$. This yields that $|u(t,x,z)|\leq C(1+z)$, for all $(t,x,z)\in\overline{\mathcal{D}_T}$.  Letting $n \rightarrow \infty$ on both sides of \eqref{eq:value-ineq}, by using Dominated Convergence Theorem and  Monotone Convergence Theorem, we get the desired result.

\begin{align}\label{eq:estimate-theta-2}
e^{r}(v_{rr}+v_r)(t,r,z)\nonumber\\
&\quad=\lambda \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s+x}\phi(s-t,x,r)f(s)dx ds\\
&\qquad +(1-\lambda)\eta z\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi(s-t,x,r)dx ds.\nonumber
\end{align}

We first consider the case with $(0,x,z)\in {\cal O}_T$ and ${\cal O}_T\neq \emptyset$. In view of Lemma \ref{lem:u_x}, the partial derivative of the value function $u$ with respect to $x$ satisfies that $u_x\in{\tt{C}}^{1,2,2}({\cal O}_T)$.  For any $t\in [0,T)$ and $\varepsilon\in(0,1)$, by applying It\^o's formula to $Y_{t\wedge (1-\varepsilon)\tau_0}=u_x({t\wedge (1-\varepsilon)\tau_0},X_{t\wedge (1-\varepsilon)\tau_0}^*,Z_{t\wedge (1-\varepsilon)\tau_0})$, we obtain
\begin{align}\label{eq:ito-Y-1}
Y_{t\wedge (1-\varepsilon)\tau_0}&=Y_0+\int_0^{{t\wedge (1-\varepsilon)\tau_0}} {\cal L}^{\theta_s^*} u_x(s,X_{s}^*)ds+\int_0^{{t\wedge (1-\varepsilon)\tau_0}}  u_{xx}(s,X_{s}^*)dL_s^X\nonumber\\
&\quad+\int_0^{{t\wedge (1-\varepsilon)\tau_0}} \left((\theta_s^*\sigma-(1-\lambda)\sigma_Z Z_s )u_{xx}(s,X_{s}^*,Z_s)+\sigma_Z Z_s u_{xz}(s,X_{s}^*,Z_s) \right) dW_s,
\end{align}
where the operator ${\cal L}^{\theta}$ with $\theta\in \mathds{R}$ acting on 
$g\in C^{1,2,2}(\mathcal{D}_T)$ is defined by
\begin{align*}
{\cal L}^{\theta}g&:=g_t+g_x\mu\theta+\frac{1}{2}g_{xx}(\sigma\theta-(1-\lambda)\sigma_Zz)^2+g_{xz}(\sigma\theta-(1-\lambda)\sigma_Zz)\sigma_Z z\\
&\quad+\frac{1}{2}\sigma_Z^2z^2g_{zz}+\mu_Z zg_z -((1-\lambda)\mu_Zz+\lambda f(t)) g_x.
\end{align*} 
We can obtain from \eqref{eq:optimal-theta} that
\begin{align}\label{eq:ito-Y-2}
& (\theta_s^*\sigma-(1-\lambda)\sigma_Z Z_s )u_{xx}(s,X_{s}^*,Z_s)+\sigma_Z Z_s u_{xz}(s,X_{s}^*,Z_s) =- \frac{\mu}{\sigma} u_{x}(s,X_{s}^*,Z_s)=- \frac{\mu}{\sigma}Y_s.
\end{align}
It follows from Theorem \ref{thm:verification} that $({\cal L}^{\theta_s^*} -\rho)u(t,x,z)=0$ for $(t,x,z)\in  {\cal O}_T$. Taking the derivative of $x$ on both sides of the equation, we have
\begin{align}\label{eq:ito-Y-3}
&\int_0^{{t\wedge (1-\varepsilon)\tau_0}}  {\cal L}^{\theta_s^*} u_x(s,X_{s}^*,Z_s)ds=\int_0^{{t\wedge (1-\varepsilon)\tau_0}} \rho  u_x(s,X_{s}^*,Z_s)ds=\int_0^{{t\wedge (1-\varepsilon)\tau_0}}  \rho Y_sds.
\end{align}
Denote by $L_t^Y=-\int_0^{t}  u_{xx}(s,X_{s}^*,Z_s)dL_s^X$ for $t\geq 0$. Consequently, it follows from \eqref{eq:ito-Y-1}-\eqref{eq:ito-Y-3} and the arbitrariness of $\varepsilon\in(0,1)$ that
\begin{align*}
dY_t= \rho Y_tdt-\frac{\mu}{\sigma}Y_tdW_t-dL_t^Y,\quad t\in(0,\tau_0).
\end{align*}
Note that $u_x(t,x,z)\leq 1$, $u_x(t,0,z)= 1$ and $u_{xx}(t,x,z)\leq 0$ for all $(t,x,z)\in{\cal O}_T$. Then,  the process $L=(L_t^Y)_{t\in[0,\tau_0)}$ is a continuous and non-decreasing process (with $L_t^{Y}=0$)  which increases on the time set $\{t\in[0,\tau_0);~Y_t=1\}$ only. This implies that  $Y$ taking values on $(0,1]$ is a reflected process and $L^Y$ is the local time process of $Y$. 

Next, we claim that $Y_t=e^{-R_t^{0,r}}$ on $[0,\tau_0)$, where  the reflected process $(R_t^{0,r})_{t\in [0,T]}$ is given by \eqref{eq:R} with $r=-\ln Y_0=-\ln v_x(0,x,z)$. Let $\tilde{Y}_t=e^{-R_t^{0,r}}$ for $t\in[0,T]$. Then, by using It\^o's rule, $\tilde{Y}=(\tilde{Y}_t)_{t\in[0,T]}$ satisfies the following dynamics given by
\begin{align*}
d\tilde{Y}_t= \rho \tilde{Y}_tdt-\frac{\mu}{\sigma}\tilde{Y}_tdW_t-dL_t^{\tilde{Y}},
\end{align*}
where $L_t^{\tilde{Y}}=\int_0^t e^{-R_t^{0,r}} dL_s^{0,r}=\int_0^t  dL_s^{0,r}=L_t^{0,r}$ for $t\in[0,T]$. We can see that $L^{\tilde{Y}}=(L_t^{\tilde{Y}})_{t\in [0,T]}$ is a continuous and non-decreasing process that increases only on $\{t \in[0, T] ;~R_s^{0,r}=0\}=\{t \in[0, T] ;~\tilde{Y}_s=1\}$ with $L_0^{\tilde{Y}}=0$. This yields that $\tilde{Y}$ is a  the reflected process and $L^{\tilde{Y}}$ is the corresponding local time process. Noting that $\tilde{Y}$ and $Y$ satisfy the same reflected SDE, by the uniqueness of the strong solution, we deduce that $Y_t=\tilde{Y}_t=e^{-R_t^{0,r}}$ on $[0,\tau_0)$. Thus, it holds that, $\mathbb{P}$-a.s.
\begin{align*}
\tau_0&=\inf\{t\in[0,T] ,~ X_t^*\geq x_0(t,Z_t)\}\wedge T=\inf\{t\in[0,T] ,~ v_x(t,X_t^*,Z_t)\leq0\}\wedge T\nonumber\\
&=\inf\{t\in[0,T] ,~ Y_t\leq 0\}\wedge T=\inf\{t\in[0,T] ,~ e^{-R_t^{0,r}}\leq 0\}\wedge T=T.
\end{align*}
Then, it is not hard to see that $Y$ satisfies the dynamic \eqref{eq:Yt} on $(0,T]$ with $Y_0=v_x(0,x,z)$.

We next let $(0,x,z)\in {\cal O}_T^c\cap \overline{\mathcal{D}}_T$. In this case, we have $x\leq x_0(0,z)$, and hence $\tau_0=0$, $\mathbb{P}$-a.s., and the value function  $u(0,x,z)=0$. Introduce ${\cal M}:=\{\omega\in\Omega;~(t,X_t^*,Z_t)\in  {\cal O}_T^c\cap \overline{\mathcal{D}}_T\}$. Assume that there exists some $t_0\in(0,T]$ such that $\mathbb{P}({\cal M})>0$. Then, it follows from the dynamic program principle and the fact $u(t,X_t^*,Z_t)<0$ on ${\cal M}$ that
\begin{align*}
0=u(0,x,z)&=\mathbb{E}\left[-\int_0^{t}e^{-\rho s}dL_s^{X^*}+e^{-\rho t}u(t,X_t^*,Z_t)\right]\leq\mathbb{E}\left[e^{-\rho t}u(t,X_t^*,Z_t){\bf 1}_{{\cal M}}\right]<0,
\end{align*}
which yields a contradiction. Thus, for any $t\in[0,T]$, we have $(t,X_t^*,Z_t)\in  {\cal O}_T^c\cap \overline{\mathcal{D}}_T$, $\mathbb{P}$-a.s., which completes the proof of the lemma.

\begin{align}\label{eq:ito-Y-1}
Y_{t\wedge (1-\varepsilon)\tau_0}&=Y_0+\int_0^{{t\wedge (1-\varepsilon)\tau_0}} {\cal L}^{\theta_s^*} u_x(s,X_{s}^*)ds+\int_0^{{t\wedge (1-\varepsilon)\tau_0}}  u_{xx}(s,X_{s}^*)dL_s^X\nonumber\\
&\quad+\int_0^{{t\wedge (1-\varepsilon)\tau_0}} \left((\theta_s^*\sigma-(1-\lambda)\sigma_Z Z_s )u_{xx}(s,X_{s}^*,Z_s)+\sigma_Z Z_s u_{xz}(s,X_{s}^*,Z_s) \right) dW_s,
\end{align}

\begin{align*}
\tau_0&=\inf\{t\in[0,T] ,~ X_t^*\geq x_0(t,Z_t)\}\wedge T=\inf\{t\in[0,T] ,~ v_x(t,X_t^*,Z_t)\leq0\}\wedge T\nonumber\\
&=\inf\{t\in[0,T] ,~ Y_t\leq 0\}\wedge T=\inf\{t\in[0,T] ,~ e^{-R_t^{0,r}}\leq 0\}\wedge T=T.
\end{align*}

In view of \eqref{eq:G} and \eqref{eq:H}, the functions $G(r,s,t)$ and $H(r,z,t)$ are non-negative and continuous.  Fix $(r,z)\in \mathds{R}_+\times (0,\infty)$. Choose $N>0$ with $0=t_0<t_1<t_2<\cdots<t_N=T$ and $t_{i+1}-t_i=T/N$ for $i=0,\ldots,N-1$ such that
\begin{align*}
M:=\sup_{i=0,...,N-1}  \sup_{t \in  [t_i,t_{i+1}]} \int_{t}^{t_{i+1}}G(r,s,t) ds<1.
\end{align*}
For $t\in [t_{N-1},t_N]$ and $f_1,f_2\in C([t_{N-1},t_N])$, we have 
\begin{align*}
|{\cal J}f_1(t)-{\cal J}f_2(t)|&=\left|\int_t^T \left(f_1(s)-f_2(s)\right) G(r,s,t)ds\right|\leq \int_t^T \left|f_1(s)-f_2(s)\right|G(r,s,t)ds\\
&\leq \sup_{s\in[t,T]}|f_1(s)-f_2(s)| \int_t^T G(r,s,t)ds\leq M \|f_1-f_2\|_{[t_{N-1},t_N]},
\end{align*}
where $\|f\|_{[t_{N-1},t_N]}:=\sup_{t\in [t_{N-1},t_N]}|f(t)|$ for $f\in{\tt{C}}([t_{N-1},t_N])$ is the uniform norm of continuous function on  $[t_{N-1},t_N]$. This implies that ${\cal J}$ is a contraction map on ${\tt{C}}([t_{N-1},t_N])$ and hence has a unique fixed point $f^N$ on $[t_{N-1},t_N]$. Furthermore, if we start with a non-negative continuous function $f_0\in{\tt{C}}([t_{N-1},t_N])$, and consider the sequence $(f_n)_{n\geq 1}$ with $f_n:={\cal J}f_{n-1}$. It follows from  $G(r,s,t)\geq 0$ and $H(r,z,t)\geq 0$ that $f_n$ is also a non-negative function, for any $n\geq 1$. As $f_n$ converges to the fixed point $f^N$, we know $f^N(t)\geq 0$ on $[t_{N-1},t_N]$. On $[t_{N-2},t_{N-1}]$, let us consider the mapping ${\cal J}^{N-1}:{\tt{C}}([t_{N-2},t_{N-1}])\mapsto{\tt{C}}([t_{N-2},t_{N-1}])$ defined by
\begin{align*}
{\cal J}^{N-1}f(t):=\int_t^{t_{N-1}}f(s)G(r,s,t)ds+\int_{t_{N-1}}^{T} f^N(s)G(r,s,t)ds+H(r,z,t),\quad \forall t\in[t_{N-2},t_{N-1}].
\end{align*}
Similarly, we can see that ${\cal J}^{N-1}$ is a contraction mapping on ${\tt{C}}([t_{N-2},t_{N-1}]\times )$ and hence has a unique fixed point $f^{N-1}(t)\geq 0$ on $[t_{N-2},t_{N-1}]$ with $f^{N-1}(t_{N-1})=f^N(t_{N-1})$. Repeating this procedure, we can get the non-negative continuous function sequence $\{f^i\}_{i=1,\ldots,N}$. Define the function $f:[0,T]\to \mathds{R}_+$ with $f(t)=f^i(t)$ for $t\in[t_{i-1},t_i]$, then the non-negative  continuous $f$ is the unique fixed point of mapping ${\cal J}$. If there exists some $t_0\in[0,T)$ such that $f(t_0)\leq0$, then let us introduce $\hat{t}:=\sup\{t\in[0,T];~f(t)\leq 0\}$. As $f(T)>0,f(t_0)\leq 0$ and $f\in{\tt{C}}([0,T])$, we have $\hat{t}\in[t_0,T)$, and 
\begin{align*}
f(\hat{t})=\int_{\hat{t}}^T f(s)G(r,s,t_0)ds+H(r,z,\hat{t})\leq 0,
\end{align*}
which contradicts with the facts that $f,G\geq 0$, $H>0$ on $(\hat{t},T]$. Thus, we complete the proof.

Fix $(r_1,t_1)\in\mathds{R}_+\times [0,T]$. For any $\epsilon\in (0,1)$ and $(r_2,t_2)\in {\cal M}^{(r_1,t_1)}_{\epsilon}:=\{(r,t)\in \mathds{R}_+\times [0,T];~|r-r_1|+|t-t_1|\leq \epsilon\}$, we have
\begin{align}\label{continuity} 
|f(t_1;r_1)-f(t_2;r_2)|\leq |f(t_1;r_1)-f(t_2;r_1)|+|f(t_2;r_1)-f(t_2;r_2)|
\end{align}
It follows from Lemma \ref{lem:fixpoint-r} that
\begin{align}\label{continuity-1}
|f(t_1;r_1)-f(t_2;r_1)|&\leq \left|\int_{t_1}^{t_2} f(s;r_1)G(r_1,s,t_1)ds\right|+\left|H(r_1,z,t_1)-H(r_1,z,t_2)\right|\nonumber\\
&\leq \max_{s\in[t_1,t_2]}|f(s;r_1)G(r_1,s,t_1)||t_2-t_1|+\left|H(r_1,z,t_1)-H(r_1,z,t_2)\right|.
\end{align}
Utilizing the continuity of $(r,s,t)\mapsto G(r,s,t)$, $(r,t)\mapsto H(r,z,t)$ and  $s\mapsto f(s;r)$, we deduce from \eqref{continuity-1} that
\begin{align}\label{continuity-2}
\lim_{\epsilon \to0}|f(t_1;r_1)-f(t_2;r_1)|=0.
\end{align}
On the other hand, applying Lemma \ref{lem:fixpoint-r} again, for $t\in[0,T]$,  we have that
\begin{align}\label{continuity-3}
&|f(t;r_1)-f(t;r_2)|\nonumber\\
&\leq\left|\int_{t}^T (f(s;r_1)-f(s;r_2))G(r_2,s,t)+(G(r_1,s,t)-G(r_2,s,t))f(s;r_1)ds\right|\nonumber\\
&\quad+\left|H(r_1,z,t)-H(r_2,z,t)\right|\nonumber\\
&\leq\int_{t}^T |f(s;r_1)-f(s;r_2)|G(r_2,s,t)ds+\max_{(s,t)\in[0,T]^2}|(G(r_1,s,t)-G(r_2,s,t))f(s;r_1)|T\nonumber\\
&\quad+\max_{s\in[0,T]}\left|H(r_1,z,t)-H(r_2,z,t)\right|\nonumber\\
&\leq K_1\int_{t}^T |f(s;r_1)-f(s;r_2)|ds+K_2(r_1,r_2),
\end{align}
where the positive constant $K_1:=\max_{(r,t_2)\in {\cal M}_1^{(r_1,t_1)},~s\in[t,T]}G(r,s,t)<+\infty$, and the function $K_2(r_1,r_2)$ is given by
\begin{align*}
K_2(r_1,r_2):=\max_{(s,t)\in[0,T]^2}|(G(r_1,s,t)-G(r_2,s,t))f(s;r_1)|T+\max_{s\in[0,T]}\left|H(r_1,z,s)-H(r_2,z,s)\right|,
\end{align*}
which satisfies $\lim_{\epsilon \to 0}K_2(r_1,r_2)\to 0$. Since \eqref{continuity-3} holds for any $t\in[0,T]$, replacing $t$ with $T-t$, we deduce that
\begin{align*}
\left|f(T-t;r_1)-f(T-t;r_2)\right|&\leq K_1\int_{T-t}^T |f(s;r_1)-f(s;r_2)|ds+K_2(r_1,r_2)\nonumber\\
&=K_1\int_{0}^t |f(T-s;r_1)-f(T-s;r_2)|ds+K_2(r_1,r_2).
\end{align*}
It follows from the Gronwall's inequality that
\begin{align}\label{continuity-4}
\lim_{\epsilon \to 0}\left|f(T-t;r_1)-f(T-t;r_2)\right|\leq \lim_{\epsilon \to 0}K_1 e^{K_2(r_1,r_2)T}=0.
\end{align}
Taking $t=T-t_2$ in \eqref{continuity-4} and noting $\lim_{\epsilon \to 0}|f(t_2;r_1)-f(t_2;r_2)|=0$, together with \eqref{continuity} and \eqref{continuity-2}, we conclude that the function $(r,t)\mapsto f(t;r)$ is continuous.
